from pathlib import Path
import os,json,hashlib,subprocess,psycopg
from psycopg.rows import dict_row
R=Path.cwd();B=R/'.evidence/gt-shared-parent-native-certificate-prepare-20261010';catalog=json.loads((B/'full-effects-catalog-current-1691.json').read_text());delta=json.loads((B/'full-ri-delta-r2-1690.json').read_text());lab=json.loads((R/'.evidence/gt-source-desktop-shm-lab-20261009/lab.json').read_text());ids=sorted({x['constraint_oid'] for x in delta['comparison_bindings']})
for k in ('PGPASSWORD','PGPASSFILE','PGSERVICE','PGSERVICEFILE','PGOPTIONS'):os.environ.pop(k,None)
with psycopg.connect(host='127.0.0.1',port=5441,user='aos_app',dbname=catalog['identity']['database'],passfile=lab['passfile'],row_factory=dict_row) as c:
 c.execute('SET TRANSACTION READ ONLY');identity=c.execute("SELECT current_database() AS database,system_identifier::text AS cluster,current_setting('transaction_read_only') AS readonly FROM pg_control_system()").fetchone();assert identity==catalog['identity']
 rows=c.execute("""SELECT k.oid::text AS constraint_oid,k.conname,k.conrelid::regclass::text AS child,k.confrelid::regclass::text AS parent,k.confmatchtype,fr.relkind AS child_kind,pr.relkind AS parent_kind,idx.i AS ordinal,v.vector,a.attname AS child_column,pa.attname AS parent_column,a.atttypid::regtype::text AS child_type,pa.atttypid::regtype::text AS parent_type,op.oid::text AS operator_oid,op.oid::regoperator::text AS operator,onsp.nspname AS operator_schema,op.oprleft::regtype::text AS left_input_type,op.oprright::regtype::text AS right_input_type,p.oid::regprocedure::text AS function,pn.nspname AS function_schema,p.prosrc AS body_symbol,l.lanname AS language,p.provolatile,pg_get_userbyid(p.proowner) AS owner,p.prosecdef,p.proconfig,encode(sha256(convert_to(p.prosrc,'UTF8')),'hex') AS body_hash FROM pg_constraint k CROSS JOIN LATERAL generate_subscripts(k.conkey,1) idx(i) CROSS JOIN LATERAL (VALUES ('pf',k.conpfeqop[idx.i]),('pp',k.conppeqop[idx.i]),('ff',k.conffeqop[idx.i])) v(vector,oid) JOIN pg_attribute a ON a.attrelid=k.conrelid AND a.attnum=k.conkey[idx.i] JOIN pg_attribute pa ON pa.attrelid=k.confrelid AND pa.attnum=k.confkey[idx.i] JOIN pg_class fr ON fr.oid=k.conrelid JOIN pg_class pr ON pr.oid=k.confrelid JOIN pg_operator op ON op.oid=v.oid JOIN pg_namespace onsp ON onsp.oid=op.oprnamespace JOIN pg_proc p ON p.oid=op.oprcode JOIN pg_namespace pn ON pn.oid=p.pronamespace JOIN pg_language l ON l.oid=p.prolang WHERE k.oid::text=ANY(%s) ORDER BY child,k.conname,idx.i,v.vector""",(ids,)).fetchall();assert len(rows)==3*76
 mismatches=[]
 for x in rows:
  lt=x['child_type'] if x['vector']=='ff' else x['parent_type'];rt=x['parent_type'] if x['vector']=='pp' else x['child_type']
  if (x['operator_schema']!='pg_catalog' or x['function_schema']!='pg_catalog' or x['language']!='internal' or x['left_input_type']!=lt or x['right_input_type']!=rt):mismatches.append(x)
 assert not mismatches
 out=dict(authority='AOS-001691',head=subprocess.check_output(['git','rev-parse','HEAD'],text=True).strip(),identity=identity,source_catalog_hash=hashlib.sha256((B/'full-effects-catalog-current-1691.json').read_bytes()).hexdigest(),fk_count=len(ids),column_pairs=76,operator_vector_count=len(rows),vectors=['pf','pp','ff'],bindings=rows,mismatches=mismatches,query_cast_required_by_type_binding=False,all_source_relations_plain_tables=all(x['child_kind']=='r' and x['parent_kind']=='r' for x in rows),distinct_native_comparison_functions=sorted({x['function'] for x in rows}),native_comparison_executed=False,full_native_effects_approved=False,formal_binary_provenance_verified=False,execution_allowed=False)
 (B/'all-ri-comparisons-1691.json').open('x').write(json.dumps(out,indent=2)+'\n');print(json.dumps({k:out[k] for k in ['fk_count','column_pairs','operator_vector_count','vectors','query_cast_required_by_type_binding','all_source_relations_plain_tables','distinct_native_comparison_functions','execution_allowed']}))
